css:
.loader {
  position: relative;
  width: 34px;
  height: 44px;
  transform-origin: bottom center;
  animation: wob 1.2s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  top: 8px;
  left: 50%;
  width: 30px;
  height: 32px;
  margin-left: -15px;
  background: #6366f1;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
}
.loader::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 50%;
  width: 30px;
  height: 11px;
  margin-left: -15px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes wob {
  0%, 100% { transform: rotate(-11deg); }
  50% { transform: rotate(11deg); }
}
